// Prepare video processing job
const input = $input.first().json.body || $input.first().json;

const job = {
  job_id: `job_${Date.now()}`,
  yacht_id: input.yacht_id,
  source_file_id: input.source_file_id,
  source_url: input.source_url,
  clips: input.clips || [],
  output_format: input.output_format || 'mp4',
  vertical: input.vertical !== false,
  burn_subtitles: input.burn_subtitles || false,
  srt_content: input.srt_content || null,
  overlays: input.overlays || [],
  output_dir: `/data/chakra9/outputs/${input.yacht_id}/${Date.now()}`,
  temp_dir: `/tmp/chakra9/${Date.now()}`,
  created_at: new Date().toISOString()
};

return [{ json: job }];

// Parse video info and prepare clip commands
const job = $('Prepare Job').first().json;
const probeRaw = $input.first().json.stdout;

let videoInfo = {};
try {
  videoInfo = JSON.parse(probeRaw);
} catch (e) {
  videoInfo = { error: 'Could not parse ffprobe output' };
}

const duration = parseFloat(videoInfo.format?.duration) || 0;
const videoStream = videoInfo.streams?.find(s => s.codec_type === 'video') || {};
const width = videoStream.width || 1920;
const height = videoStream.height || 1080;
const isVertical = height > width;

// Generate FFmpeg commands for each clip
const clipCommands = job.clips.map((clip, idx) => {
  const clipNum = String(idx + 1).padStart(2, '0');
  const outputFile = `${job.output_dir}/clip_${clipNum}.mp4`;

  // Base FFmpeg command
  let cmd = `ffmpeg -y -i ${job.temp_dir}/source.mp4`;

  // Time range
  cmd += ` -ss ${clip.start_sec} -to ${clip.end_sec}`;

  // Video filters
  const filters = [];

  // Crop to vertical (9:16) if needed and requested
  if (job.vertical && !isVertical) {
    const cropWidth = Math.floor(height * 9 / 16);
    const cropX = Math.floor((width - cropWidth) / 2);
    filters.push(`crop=${cropWidth}:${height}:${cropX}:0`);
    filters.push('scale=1080:1920');
  } else if (job.vertical) {
    filters.push('scale=1080:1920:force_original_aspect_ratio=decrease');
    filters.push('pad=1080:1920:(ow-iw)/2:(oh-ih)/2');
  }

  // Add text overlays
  if (clip.overlays && clip.overlays.length > 0) {
    clip.overlays.forEach((overlay, oi) => {
      const text = overlay.text.replace(/'/g, "\\'");
      const fontsize = overlay.style === 'bold' ? 72 : 56;
      const yPos = overlay.position === 'top' ? 100 : (overlay.position === 'bottom' ? 'h-th-100' : '(h-th)/2');
      filters.push(`drawtext=text='${text}':fontsize=${fontsize}:fontcolor=white:borderw=3:bordercolor=black:x=(w-tw)/2:y=${yPos}`);
    });
  }

  if (filters.length > 0) {
    cmd += ` -vf "${filters.join(',')}"`;
  }

  // Output settings
  cmd += ` -c:v libx264 -preset fast -crf 23 -c:a aac -b:a 128k`;
  cmd += ` ${outputFile}`;

  return {
    clip_id: clip.clip_id || `clip_${clipNum}`,
    clip_num: clipNum,
    command: cmd,
    output_file: outputFile,
    start_sec: clip.start_sec,
    end_sec: clip.end_sec,
    duration_sec: clip.end_sec - clip.start_sec
  };
});

return [{
  json: {
    job,
    videoInfo: {
      duration,
      width,
      height,
      isVertical
    },
    clipCommands
  }
}];

// Collect all processed clips
const job = $('Prepare Job').first().json;
const clipResults = $('FFmpeg: Cut Clip').all();
const clipCommands = $('Prepare FFmpeg Commands').first().json.clipCommands;

const results = clipCommands.map((cmd, idx) => {
  const result = clipResults[idx]?.json || {};
  return {
    clip_id: cmd.clip_id,
    output_file: cmd.output_file,
    duration_sec: cmd.duration_sec,
    success: result.exitCode === 0 || !result.stderr?.includes('Error'),
    error: result.stderr?.includes('Error') ? result.stderr : null
  };
});

const successCount = results.filter(r => r.success).length;

return [{
  json: {
    job_id: job.job_id,
    yacht_id: job.yacht_id,
    output_dir: job.output_dir,
    total_clips: results.length,
    success_count: successCount,
    failed_count: results.length - successCount,
    clips: results,
    completed_at: new Date().toISOString()
  }
}];
